var userConnection = this.Get<UserConnection>("UserConnection");

var owner = Get<Guid>("BPOwner");

var projectId = Get<Guid>("BPProjectId");
var projectNumber = Get<String>("BPProjectNumber");
var projectName = Get<String>("BPProjectName");

var MessageBody = JsonConvert.SerializeObject(new { OwnId = owner.ToString(),
													ProjectNumber = projectNumber,
													ProjectName = projectName,
													ProjectId = projectId});

BPMSoft.Configuration.MsgChannelUtilities.PostMessage(userConnection, "ProjectOnTheGo", MessageBody);

return true;
